namespace ghidra.app.plugin.core.debug.gui.emulation;



using db;
using ghidra.app.services;
using ghidra.@base.widgets.table;
using ghidra.program.model.data;
using ghidra.program.model.listing;

class VarDataTypeEditor : AbstractDataTypeTableCellEditor {
	static readonly VarDataTypeEditor INSTANCE = new VarDataTypeEditor();

	/* @Override */
	protected bool validateSelection(DataType dataType, TableModel model) {
		if (!(model is VarTableModel<object,object> vModel)) {
			return false;
		}

		VarRow row = vModel.getModelData().get(table.getEditingRow());
		if (row == null) {
			return false;
		}
		int dtLength = dataType.getLength();
		if (dtLength != -1 && dtLength != row.length) {
			vModel.getDialog()
					.setStatusText("Invalid DataType %s. Length must be %d.".formatted(dataType,
						row.length));
			return false;
		}
		return true;
	}

	/* @Override */
	protected DataTypeManagerService getService(TableModel model) {
		if (!(model is VarTableModel<object,object> vModel)) {
			return null;
		}
		return vModel.getServiceProvider().getService(typeof(DataTypeManagerService));
	}

	/* @Override */
	protected DataType resolveSelection(DataType dataType, TableModel model) {
		if (dataType == null || !(model is VarTableModel<object,object> vModel)) {
			return null;
		}
		Program program = vModel.getProgram();
		using (Transaction tx = program.openTransaction("Resolve DataTye"))
{
			return program.getDataTypeManager().resolve(dataType, null);
		}
	}
}
